import{z as s,x as A,o as t,c as B,q as r,j as i,D as E,d as o,s as n,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"子类型与协变逆变","description":"","frontmatter":{"title":"子类型与协变逆变","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/subtyping-variance.md","filePath":"cs/subtyping-variance.md","lastUpdated":1791063341000}'),p={name:"cs/subtyping-variance.md"};function c(C,a,m,F,u,D){const l=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="子类型与协变逆变" tabindex="-1">子类型与协变逆变 <a class="header-anchor" href="#子类型与协变逆变" aria-label="Permalink to &quot;子类型与协变逆变&quot;">​</a></h1><div class="epigraph"><p>$S\\lt :T$ 表示 $S$ 的值可用在要 $T$ 的地方。函数在参数上逆变、在结果上协变；容器的可变性决定能不能协变。</p><footer>—— 据 Cardelli, Type Systems；Pierce TAPL 第 15–16 章；Liskov, Data Abstraction and Hierarchy 整理</footer></div><p>上一课<a href="/cs/let-polymorphism">值限制</a>处理量化与可变。缺口是另一轴：<strong>子类型</strong>——名义或结构的宽化，以及数组/函数的变型（variance）。主干<a href="/cs/overload-coerce">overload 与强制</a>有强制转换；本课钉 \\(\\lt :\\) 规则，不把 Java 数组协变的历史事故当推荐设计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 合一对称。面向对象与记录：<code>Dog &lt;: Animal</code> 则 <code>Dog</code> 的值可传给要 <code>Animal</code> 的参数（宽度子类型可再谈字段）。函数：若用 \\(S\\to U\\) 去填 \\(T\\to V\\) 的坑，需要 \\(T\\lt :S\\)（参数更挑剔）且 \\(U\\lt :V\\)（结果更宽大）。缺口是<strong>变型</strong>，不是再写 W。</p><p>可变数组：写与读同时存在，只该不变（invariant）。Java 历史上让数组协变，运行时 <code>ArrayStoreException</code>——类型在静态上不健全。</p><p><span class="marginnote">数字实例看这个坑：Java 里 <code>Animal[] a = new Dog[1]</code> 合法（数组协变），随后 <code>a[0] = new Cat()</code> 编译能过、运行时抛 <code>ArrayStoreException</code>。编译器在每个数组写入点插运行时检查，就是在补这个静态漏洞。</span></p><h3 id="不是继承图的别名" tabindex="-1"><code>&lt;:</code> 不是继承图的别名 <a class="header-anchor" href="#不是继承图的别名" aria-label="Permalink to &quot;`&lt;:` 不是继承图的别名&quot;">​</a></h3><p>继承可诱导名义子类型；结构子类型看字段。强制（<code>int</code> 到 <code>float</code>）有时不是子类型而是另一次转换。不要混。</p><p><span class="marginnote">Pierce TAPL 子类型章。Cardelli 综述。Liskov 替换原则是规格层，本课用它对照「能不能代换」与「函数变型」。Appel 在面向对象章点过方法类型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给出记录的宽度/深度规则（点名即可）。函数变型按上面陈述。泛型参数标 <code>+</code>/<code>-</code>/<code>0</code>（Scala/Kotlin 习惯），检查定义体是否遵守。检查算法：加入子类型约束后不再是对称合一，要用边界或双向检查（后课渐进也会用）。</p>',12)),(t(),i(d,null,{default:E(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USE%5B%22%E8%A6%81%20T%22%5D%20--%3E%20SUB%5B%22%E6%9C%89%20S%20%E4%B8%94%20S%20%EF%BC%9C%3A%20T%22%5D%0A%20%20FUN%5B%22S%E2%86%92U%20%EF%BC%9C%3A%20T%E2%86%92V%22%5D%20--%3E%20CONTRA%5B%22T%20%EF%BC%9C%3A%20S%22%5D%0A%20%20FUN%20--%3E%20CO%5B%22U%20%EF%BC%9C%3A%20V%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 HM：可先实例化再问子类型，或把量化与子类型合成（有界量化 \\(\\forall\\alpha\\lt :T\\)），本课点名，不写 System F\\({}_{\\lt :}\\) 全文。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：协变指变型方向与子类型方向一致——Dog 比 Animal「小」，Dog 的生产者也比较「小」；逆变指方向相反——参数位置越具体，整个函数类型反而越「小」。口诀：产出协变、消费逆变（PECS）。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[o("可变引用："),e("code",null,"ref S <: ref T"),o(" 只当 \\(S=T\\)。只读视图可以协变；只写可以逆变。这与值限制同一精神：可变破坏宽化。")],-1)),a[7]||(a[7]=e("p",null,"不要为了「方便把 Dog[] 当 Animal[]」牺牲健全性；API 用不变泛型或只读切片。",-1)),a[8]||(a[8]=e("p",null,"把上面规则收成一张决策图，容器设计时照着走。",-1)),(t(),i(d,null,{default:E(()=>[n(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%B9%E5%99%A8%E6%88%96%E5%BC%95%E7%94%A8%E8%AF%A5%E9%80%89%E5%93%AA%E7%A7%8D%E5%8F%98%E5%9E%8B%22%5D%20--%3E%20Q%7B%22%E5%90%8C%E6%97%B6%E5%BC%80%E6%94%BE%E8%AF%BB%E5%92%8C%E5%86%99%E5%90%97%22%7D%0A%20%20Q%20--%20%22%E5%8F%AA%E6%9C%89%E8%AF%BB%EF%BC%88%E7%94%9F%E4%BA%A7%E8%80%85%EF%BC%89%22%20--%3E%20COV%5B%22%E5%8D%8F%E5%8F%98%20%2B%EF%BC%9ADog%20%E5%88%97%E8%A1%A8%E5%8F%AF%E5%BD%93%20Animal%20%E5%88%97%E8%A1%A8%E7%94%A8%22%5D%0A%20%20Q%20--%20%22%E5%8F%AA%E6%9C%89%E5%86%99%EF%BC%88%E6%B6%88%E8%B4%B9%E8%80%85%EF%BC%89%22%20--%3E%20CON%5B%22%E9%80%86%E5%8F%98%20-%EF%BC%9A%E6%94%B6%20Animal%20%E7%9A%84%E5%86%99%E5%85%A5%E5%99%A8%E5%8F%AF%E5%BD%93%E6%94%B6%20Dog%20%E7%9A%84%E7%94%A8%22%5D%0A%20%20Q%20--%20%22%E8%AF%BB%E5%86%99%E9%83%BD%E6%9C%89%22%20--%3E%20INV%5B%22%E4%B8%8D%E5%8F%98%EF%BC%9A%E6%B3%9B%E5%9E%8B%E5%8F%82%E6%95%B0%E5%BF%85%E9%A1%BB%E4%B8%A5%E6%A0%BC%E7%9B%B8%E5%90%8C%22%5D%0A%20%20INV%20--%3E%20SAFE%5B%22%E5%90%A6%E5%88%99%E5%86%99%E5%85%A5%E7%88%B6%E7%B1%BB%E4%BC%9A%E7%82%B8%E5%87%BA%E8%BF%90%E8%A1%8C%E6%97%B6%E7%B1%BB%E5%9E%8B%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<p><span class="marginnote">初学者容易以为「不变（invariant）」是保守的设计缺陷，实际上它是唯一能让写入检查成立的方案：若 <code>ref Animal</code> 能当 <code>ref Dog</code> 用，往里写一只 Cat 就违反了 Dog 引用对使用者的承诺。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多重继承的 C3，不算结构子类型的判定复杂度细节。后课默认：函数参数逆变、结果协变；可变不变。下一课泛型实现：单态化对擦除——变型在擦除语言里靠桥接方法。</p><p>也不把 Python 的鸭子类型当静态 \\(\\lt :\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>子类型是安全代换；函数参数逆变、结果协变。</li><li>可变容器应不变。</li><li>与 HM 量化正交，可合成有界量化。</li><li>出处：Pierce TAPL；Cardelli；对照 Liskov。</li></ul>',6))])}const h=s(p,[["render",c]]);export{f as __pageData,h as default};
